// Generated by scripts/build-sketch.py from the corresponding model source.
import { defineModel } from "../engine.js?v=ca81df070cc8";

export const makeScene = (S, M) => {
  const C = {
    table: '#f2e6d0', board: '#fff7e6', dark: '#d9c3a0', base: '#dfe6ee', arm: '#7d8fb3', joint: '#5c677d',
    finger: '#c3cad6', white: '#fff1c1', black: '#4a4f5c', signal: '#8ac926', ray: '#d9ff9e', skin: '#e3b8f0', steel: '#a9b4c2'
  };

  /* ───────── 1. 几何常数 ───────── */
  const SQ = 4.5, BT = 1.5;                                    // 格宽、棋盘厚（棋盘顶面 y = BT）
  const sqX = (rank) => (4.5 - rank) * SQ;                     // 第 1 行靠你（+x），第 8 行靠机器人
  const sqZ = (file) => (3.5 - 'abcdefgh'.indexOf(file)) * SQ; // a 列在 +z
  const sq = (s) => [sqX(+s[1]), BT, sqZ(s[0])];
  const BASE = { x0: -31, x1: -19.5, y1: 10, z: 10 };          // 底座
  const BX = -25, TUR_Y = BASE.y1 + 1.5, SH_Y = BASE.y1 + 6;   // 转台中心、肩关节高度
  const L1 = 22, L2 = 20, GRIP = 7;                            // 大臂、小臂、腕关节到指尖
  const MAST = { x: -29.5, z: -8.5, top: 45 }, CAM = [0, 42.6, 0];       // 摄像头支架、镜头
  const GRAB_H = 2.6, F_OPEN = 2.3, F_SHUT = 1.35;              // 夹在棋子“脖子”的高度；手指张开 / 夹紧时离中心
  const HOME = [-15, 25, 0];                                   // 机械臂待机时指尖位置
  const MOVE_W = ['e2', 'e4'], MOVE_B = ['e7', 'e5'];

  /* ───────── 2. 运动模型 ───────── */
  const sm = M.smooth, lerp3 = (a, b, t) => a.map((v, i) => v + (b[i] - v) * t);
  // 关键帧插值：keys = [[u, value], …]，value 是数或 3 维点
  const track = (keys) => (u) => {
    if (u <= keys[0][0]) return keys[0][1];
    for (let i = 1; i < keys.length; i++) if (u <= keys[i][0]) {
      const [u0, a] = keys[i - 1], [u1, b] = keys[i], t = sm(u0, u1, u);
      return Array.isArray(a) ? lerp3(a, b, t) : a + (b - a) * t;
    }
    return keys[keys.length - 1][1];
  };
  const up = (p, h) => [p[0], h, p[2]];
  const b0 = sq(MOVE_B[0]), b1 = sq(MOVE_B[1]), w0 = sq(MOVE_W[0]), w1 = sq(MOVE_W[1]);
  const LIFT = 14, grabY = BT + GRAB_H;
  const tip = track([[0.40, HOME], [0.49, up(b0, LIFT)], [0.555, up(b0, grabY)], [0.62, up(b0, grabY)], [0.665, up(b0, LIFT)],
    [0.745, up(b1, LIFT)], [0.80, up(b1, grabY)], [0.835, up(b1, grabY)], [0.875, up(b1, LIFT)], [0.94, HOME]]);
  const openF = track([[0.555, 1], [0.60, 0], [0.80, 0], [0.83, 1]]);               // 1 张开，0 夹紧
  const heldB = (u) => u > 0.6 && u < 0.81;
  const pinch = track([[0.0, [34, 16, -6]], [0.05, up(w0, 9)], [0.075, up(w0, grabY)], [0.085, up(w0, grabY)], [0.115, up(w0, 9)],
    [0.14, up(w1, 9)], [0.155, up(w1, grabY)], [0.165, up(w1, grabY)], [0.18, [34, 16, -6]]]);
  const heldW = (u) => u > 0.08 && u < 0.16;
  // 两只兵的位置（底面中心）；0.94 以后“复位”，淡出淡入回到开局格
  const pawnW = (u) => (u < 0.08 ? w0 : heldW(u) ? up(pinch(u), pinch(u)[1] - GRAB_H) : u < 0.94 ? w1 : w0);
  const pawnB = (u) => (u < 0.6 ? b0 : heldB(u) ? up(tip(u), tip(u)[1] - GRAB_H) : u < 0.94 ? b1 : b0);
  const resetA = (u) => 1 - M.pulse(u, 0.955, 0.985, 0.015);
  // 逆运动学：指尖目标 → 转台偏航 ψ、肩 q1、肘 q2（肘在上）、腕（让夹爪始终竖直朝下）
  function ik(p) {
    const W = [p[0], p[1] + GRIP, p[2]], dx = W[0] - BX, dz = W[2], r = Math.hypot(dx, dz), h = W[1] - SH_Y;
    const d = Math.min(L1 + L2 - 1e-6, Math.hypot(r, h)), c = (d * d - L1 * L1 - L2 * L2) / (2 * L1 * L2);
    const q2 = -Math.acos(M.clamp(c, -1, 1)), q1 = Math.atan2(h, r) - Math.atan2(L2 * Math.sin(q2), L1 + L2 * Math.cos(q2));
    const deg = (x) => x / M.D2R;
    return { psi: deg(Math.atan2(-dz, dx)), q1: deg(q1), q2: deg(q2), wr: -90 - deg(q1 + q2), reach: d };
  }

  /* ───────── 3. 形状 ───────── */
  const lathe = (pr) => S.lathe(pr, { seg: 14 });
  const PIECE = {
    p: [[1.45, 0], [1.45, 0.5], [0.95, 0.9], [0.55, 2.1], [0.9, 2.45], [0.55, 2.65], [0.95, 3.25], [0.75, 3.85], [0.3, 4.15], [0, 4.2]],
    r: [[1.6, 0], [1.6, 0.55], [1.1, 1.0], [0.95, 3.5], [1.3, 3.8], [1.3, 4.8], [0, 4.8]],
    q: [[1.65, 0], [1.65, 0.55], [1.05, 1.0], [0.6, 4.2], [1.15, 4.6], [0.8, 5.2], [0.45, 5.5], [0.35, 5.9], [0, 6.0]],
    k: [[1.7, 0], [1.7, 0.55], [1.1, 1.0], [0.65, 4.6], [1.2, 5.0], [0.9, 5.6], [0, 5.8]]
  };
  const piece = (t, at) => { let m = lathe(PIECE[t]); if (t === 'k') m = S.merge(m, S.xf(S.box(0.4, 1.4, 0.4), { at: [0, 6.4, 0] }), S.xf(S.box(1.1, 0.4, 0.4), { at: [0, 6.5, 0] })); return S.xf(m, { at }); };
  const setOf = (list) => S.merge(...list.map(([t, s]) => piece(t, sq(s))));
  const files = 'abcdefgh'.split('');
  const WHITE = [...files.filter((f) => f !== 'e').map((f) => ['p', f + '2']), ['r', 'a1'], ['r', 'h1'], ['q', 'd1'], ['k', 'e1']];
  const BLACK = [...files.filter((f) => f !== 'e').map((f) => ['p', f + '7']), ['r', 'a8'], ['r', 'h8'], ['q', 'd8'], ['k', 'e8']];
  const darkSquares = S.merge(...Array.from({ length: 64 }, (_, i) => i).filter((i) => (Math.floor(i / 8) + (i % 8)) % 2 === 0)
    .map((i) => S.xf(S.box(SQ, 0.06, SQ), { at: [sqX(1 + Math.floor(i / 8)), BT + 0.03, sqZ(files[i % 8])] })));
  const link = (L, w, t) => S.merge(S.xf(S.box(L, w, t), { at: [L / 2, 0, 0] }), S.xf(S.cyl(w * 0.62, t + 0.4, { axis: 'z', seg: 18 }), { at: [0, 0, 0] }),
    S.xf(S.cyl(w * 0.62, t + 0.4, { axis: 'z', seg: 18 }), { at: [L, 0, 0] }));
  const fingerAng = [0, 120, 240];
  const handMesh = S.merge(S.xf(S.sphere(1, { seg: 16, rings: 9 }), { at: [4.5, 5.2, 0], scale: [4.2, 2.2, 3.6] }),
    S.tube(S.curve([[2.5, 4.5, 1.6], [0.8, 2.2, 1.2], [0, 0, 0.75]], 4), 0.75, { seg: 8 }),
    S.tube(S.curve([[2.8, 4.6, -1.8], [1.0, 2.4, -1.4], [0, 0, -0.75]], 4), 0.8, { seg: 8 }),
    S.xf(S.cyl(2.6, 9, { axis: 'x', r2: 3.0, seg: 16 }), { at: [12, 6.2, 0] }));

  /* ───────── 4. 部件 ───────── */
  const parts = [
    { id: 'table', role: 'ground', mesh: S.box(84, 1, 58), at: [-2, -0.5, 0], color: C.table, hatch: false, pick: false, dim: false, name: '桌面' },
    { id: 'board', mesh: S.box(8 * SQ + 2, BT, 8 * SQ + 2, { sub: 4 }), at: [0, BT / 2, 0], color: C.board, hatch: false, label: '磁吸棋盘', anchor: [8 * SQ / 2 + 1, BT, 8 * SQ / 2 + 1],
      note: '棋盘和棋子里都有磁铁（产品规格写明“磁吸”），棋子放得稳，机械臂或人手轻碰也不容易倒。' },
    { id: 'squares', mesh: darkSquares, color: C.dark, hatch: false, pick: false, dim: false, name: '深色格' },
    { id: 'whiteSet', mesh: setOf(WHITE), color: C.white, hatch: false, name: '白棋', dim: false },
    { id: 'blackSet', mesh: setOf(BLACK), color: C.black, hatch: false, name: '黑棋', dim: false },
    { id: 'pawnW', mesh: piece('p', [0, 0, 0]), color: C.white, dim: false, label: '你的兵', anchor: [0, 4.2, 0], note: '你走 e2 → e4。机器人不需要你按什么按钮——它靠摄像头看出来哪一格变了。' },
    { id: 'pawnB', mesh: piece('p', [0, 0, 0]), color: C.black, dim: false, label: '它的兵', anchor: [0, 4.2, 0], note: '机器人这一步走 e7 → e5（图里的走法是示意）。' },

    // 底座 + 电路
    { id: 'base', role: 'shell', mesh: S.box(BASE.x1 - BASE.x0, BASE.y1, BASE.z * 2, { sub: 2 }), at: [(BASE.x0 + BASE.x1) / 2, BASE.y1 / 2, 0], color: C.base,
      label: '底座', anchor: [BASE.x1, BASE.y1 * 0.6, 6], note: '整机约 57 × 47 × 38.5 cm、5 kg（产品规格）。点“透视”看里面的主控板和转台电机。' },
    { id: 'pcb', role: 'inside', in: 'base', mesh: S.merge(S.box(9, 0.3, 16), S.xf(S.box(2.4, 0.8, 2.4), { at: [1, 0.55, -3] }), S.xf(S.box(1.6, 0.6, 3), { at: [-2.5, 0.45, 4] })),
      at: [-26.5, 2.2, 0], color: C.signal, glow: 'active', label: 'AI 主控板',
      note: '跑两件事：视觉算法从照片里认出每个棋子在哪；下棋引擎算下一步。产品标称 26 档难度，最高 ELO 3200（另一处写 25 档）。' },
    { id: 'turretMotor', role: 'inside', in: 'base', mesh: S.cyl(2.6, 4, { seg: 18 }), at: [BX, BASE.y1 - 2.2, 0], color: C.joint, name: '转台电机' },
    { id: 'turret', mesh: S.merge(S.cyl(5, 3, { seg: 30 }), S.xf(S.box(3.4, 4.5, 5.6), { at: [0, 3.2, 0] })), at: [BX, TUR_Y, 0], color: C.arm, group: 'arm',
      label: '旋转台', anchor: [5, 0, 0], note: '第 1 个关节：整条手臂左右转，对准要去的那一列。' },
    { id: 'shoulderMotor', parent: 'turret', mesh: S.cyl(2.2, 2.6, { axis: 'z', seg: 18 }), at: [0, SH_Y - TUR_Y, 4.2], color: C.joint, group: 'arm', label: '关节电机',
      note: '肩、肘各一个电机（示意），配减速和角度反馈，才能做到产品写的“毫米级精度”。' },
    { id: 'upper', parent: 'turret', mesh: link(L1, 2.8, 2.2), at: [0, SH_Y - TUR_Y, 0], color: C.arm, group: 'arm', label: '机械臂', anchor: [L1 / 2, 1.4, 1.1],
      note: '产品规格写的是“4 自由度机械臂”。这里画成：转台 + 肩 + 肘 + 腕，腕关节让夹爪始终竖直朝下（关节排法是示意）。' },
    { id: 'elbowMotor', parent: 'upper', mesh: S.cyl(1.8, 2.4, { axis: 'z', seg: 16 }), at: [L1, 0, 2.3], color: C.joint, group: 'arm', name: '肘关节电机' },
    { id: 'fore', parent: 'upper', mesh: link(L2, 2.3, 1.9), at: [L1, 0, 0], color: C.arm, group: 'arm', name: '小臂' },
    { id: 'wrist', parent: 'fore', mesh: S.merge(S.cyl(1.3, 2.4, { axis: 'z', seg: 14 }), S.xf(S.cyl(1.8, 2.2, { axis: 'x', seg: 16 }), { at: [1.1, 0, 0] })), at: [L2, 0, 0],
      color: C.joint, group: 'arm', name: '腕关节' },
    ...fingerAng.map((a, i) => ({ id: 'finger' + i, parent: 'wrist', group: 'grip',
      mesh: S.merge(S.xf(S.box(4.6, 0.45, 0.9), { at: [GRIP - 2.3, 0, 0] }), S.xf(S.box(0.9, 0.7, 1.0), { at: [GRIP - 0.45, -0.25, 0] })),
      at: [0, 0, 0], rot: [a, 0, 0], color: C.finger, label: i === 0 ? '三指软爪' : undefined, name: '软爪手指', anchor: [GRIP - 1, 0, 0],
      note: '三根手指同时收拢，从三面夹住棋子的“脖子”。厂商说是软爪、力度可控，不会夹坏棋子。' })),

    // 摄像头支架
    { id: 'mast', mesh: S.tube([[MAST.x, BASE.y1, MAST.z], [MAST.x, MAST.top, MAST.z], [MAST.x + 3, MAST.top + 1.5, MAST.z + 0.9], [CAM[0] - 3, MAST.top + 1.5, -0.8]], 0.9, { seg: 10 }),
      color: C.steel, pick: false, name: '摄像头支架' },
    { id: 'camera', mesh: S.merge(S.xf(S.box(6, 2.4, 4.4), { at: [0, MAST.top + 0.6, 0] }), S.xf(S.cyl(1.1, 1.6, { seg: 16 }), { at: [0, CAM[1] + 1.0, 0] })),
      at: [CAM[0], 0, CAM[2]], color: C.joint, glow: 'active', label: '对局摄像头', anchor: [0, MAST.top, 0],
      note: '从正上方看整张棋盘。你每走一步，它拍一张，和上一张比，就知道哪颗子从哪格到了哪格。厂商宣称识别率超过 99.9%。' },
    { id: 'lens', mesh: S.cyl(0.8, 0.3, { seg: 14 }), at: [CAM[0], CAM[1] + 0.05, CAM[2]], color: C.signal, glow: 'active', pick: false, name: '镜头' },

    // 你的手（示意）
    { id: 'hand', mesh: handMesh, color: C.skin, label: '你的手（示意）', anchor: [4.5, 7.4, 0], note: '人走子时，机器人在等；图里没有画任何“检测到手就停”的功能，因为没查到出处。' }
  ];

  /* ───────── 拆开（E）：转台连手臂往上，关节电机往侧面，手指往外往下；主控板从底座侧面抽出，摄像头往上 ───────── */
  const EXPLODE = {
    turret: [0, 8, 0], turretMotor: [0, 4, 0], shoulderMotor: [0, 0, 7], upper: [0, 3, 0], elbowMotor: [0, 0, 6], fore: [0, 2, 0], wrist: [0, 2, 0],
    pcb: [0, 0, -18], mast: [0, 12, 0], camera: [0, 18, 0], lens: [0, 18, 0]
  };
  fingerAng.forEach((a, i) => { EXPLODE['finger' + i] = [3 * Math.cos(a * M.D2R), -3, 3 * Math.sin(a * M.D2R)]; });
  parts.forEach((p) => { if (EXPLODE[p.id]) p.explode = EXPLODE[p.id]; });

  /* ───────── 5. 零件清单（Truth first） ───────── */
  const MANIFEST = {
    board: { on: 'table' }, squares: { on: 'board' }, whiteSet: { on: 'board' }, blackSet: { on: 'board' },
    pawnW: { on: ['board', 'hand'] }, pawnB: { on: ['board', 'finger0', 'finger1', 'finger2'] },   // 不在棋盘上时，就必须在手里 / 爪里
    base: { on: 'table' }, pcb: { on: 'base' }, turretMotor: { on: 'base' }, turret: { on: ['base', 'turretMotor'] },
    shoulderMotor: { on: 'turret' }, upper: { on: 'turret' }, elbowMotor: { on: 'upper' }, fore: { on: 'upper' }, wrist: { on: 'fore' },
    finger0: { on: 'wrist' }, finger1: { on: 'wrist' }, finger2: { on: 'wrist' },
    mast: { on: 'base', connects: ['base', 'camera'] }, camera: { on: 'mast' }, lens: { on: 'camera' },
    hand: { on: 'free' }
  };

  /* ───────── 6. 粒子流 ───────── */
  const lensPt = [CAM[0], CAM[1] - 0.4, CAM[2]];
  const rays = [[-16, BT + 0.1, -16], [16, BT + 0.1, -16], [16, BT + 0.1, 16], [-16, BT + 0.1, 16], [sqX(4), BT + 0.1, sqZ('e')]];
  const flows = [
    ...rays.map((p, i) => ({ id: 'ray' + i, role: 'part', from: 'board', to: 'lens', color: C.ray, count: 9, speed: 2.2, size: 0.55, path: [p, lensPt] })),
    { id: 'sig', role: 'part', from: 'camera', to: 'pcb', color: C.signal, count: 22, speed: 2.4, size: 0.5,
      path: [[CAM[0] - 2.5, MAST.top + 1.5, -0.8], [MAST.x + 3, MAST.top + 1.5, MAST.z + 0.9], [MAST.x, MAST.top, MAST.z], [MAST.x, BASE.y1, MAST.z], [-27, 2.6, -4]] },
    { id: 'cmd', role: 'part', from: 'pcb', to: 'turret', color: C.signal, count: 10, speed: 2.4, size: 0.5, path: [[-26, 2.6, 0], [BX, 6, 0], [BX, TUR_Y, 0]] }
  ];

  /* ───────── 7. 步骤 + 按钮 ───────── */
  const steps = [
    { name: '你走一步', from: 0, to: 0.18, color: C.skin, active: ['hand', 'pawnW'], view: { yaw: 20, pitch: 30, zoom: 1.6, focus: [6, 6, -2] },
      text: '你执白，把 e2 的兵推到 e4。棋子底下有磁铁，放下就吸住。' },
    { name: '拍照识别', from: 0.18, to: 0.3, color: C.ray, active: ['camera', 'lens', 'board'], flows: rays.map((_, i) => 'ray' + i), view: { yaw: -20, pitch: 22, zoom: 1.35, focus: [-4, 14, 0] },
      text: '支架上的摄像头从正上方拍下整张棋盘，和上一张比：e2 空了、e4 多了一颗白兵——你走的是 e2→e4。' },
    { name: 'AI 思考', from: 0.3, to: 0.4, color: C.signal, active: ['pcb', 'camera'], flows: ['sig'], view: { yaw: -60, pitch: 18, zoom: 1.7, focus: [-25, 8, 0] },
      text: '照片送进底座里的主控板：先认出棋局，再让下棋引擎算出这一步走 e7→e5。难度可以调，产品标称最高 ELO 3200。' },
    { name: '伸臂抓子', from: 0.4, to: 0.62, color: C.arm, active: ['arm', 'grip', 'pawnB'], flows: ['cmd'], view: { yaw: -35, pitch: 16, zoom: 1.5, focus: [-14, 10, 0] },
      text: '主控板算出每个关节该转多少（逆运动学）：转台对准 e 列，肩、肘把手送到 e7 正上方，腕关节让爪子一直竖直朝下；下降、三指收拢夹住兵。' },
    { name: '搬子落子', from: 0.62, to: 0.84, color: C.arm, active: ['arm', 'grip', 'pawnB'], view: { yaw: -35, pitch: 16, zoom: 1.5, focus: [-8, 10, 0] },
      text: '先抬高再平移，避免碰倒别的棋子；到 e5 上方垂直放下，手指张开，磁铁把兵吸在格子中间。' },
    { name: '收臂 · 等你', from: 0.84, to: 1, color: C.joint, active: ['arm'], view: { yaw: -20, pitch: 22, zoom: 1.35, focus: [-4, 14, 0] },
      text: '机械臂回到待机位置，让出棋盘，轮到你。（动画最后把两只兵放回开局格，方便再看一遍。）' }
  ];
  const buttons = [
    { id: 'move', label: '我走一步', steps: [1] },
    { id: 'snap', label: '拍照识别', steps: [2], hint: '先走一步，它才有东西可看' },
    { id: 'think', label: 'AI 思考', steps: [3], hint: '还没认出你走了哪一步，先按「拍照识别」' },
    { id: 'grab', label: '伸臂抓子', steps: [4], hint: '还没想好走哪一步，先按「AI 思考」' },
    { id: 'place', label: '落子', steps: [5], hint: '手里还没有棋子，先按「伸臂抓子」' },
    { id: 'home', label: '收臂', steps: [6] }
  ];

  return {
    manifest: MANIFEST,
    fig: '图 09',
    title: '下棋机器人：看一眼、想一下、伸手走一步',
    subtitle: '参考 SenseRobot（元萝卜）：4 自由度机械臂 · 对局摄像头 · 三指软爪 · 磁吸棋盘 · 57 × 47 × 38.5 cm · 5 kg',
    view: { yaw: -20, pitch: 22, zoom: 1.35, focus: [-4, 14, 0] },
    xray: false, cycle: 16, labels: 'step',
    mode: 'buttons', buttons, order: 'strict',
    hint: '按下面的按钮一步步来 · 拖动旋转 · X 透视看底座里面 · M 切换自动循环',
    closeups: [
      { name: 'gripper', focus: [b0[0], 6, b0[2]], step: 4, at: 0.92, zoom: 4, yaw: -60, pitch: 8 },
      { name: 'place', focus: [b1[0], 5, b1[2]], step: 5, at: 0.85, zoom: 4, yaw: 30, pitch: 10 },
      { name: 'camera', focus: [0, 43, 0], step: 2, zoom: 4, yaw: -30, pitch: -10 },
      { name: 'base', focus: [-25, 8, 0], step: 3, zoom: 3, yaw: -120, pitch: 18, xr: 1 },
      { name: 'hand', focus: [w0[0], 4, w0[2]], step: 1, at: 0.5, zoom: 3.5, yaw: 40, pitch: 12 }
    ],
    parts, flows, steps,
    animate(u, api) {
      const J = ik(tip(u)), o = openF(u), rF = F_SHUT + (F_OPEN - F_SHUT) * o;
      api.set('turret', { rot: [0, J.psi, 0] });
      api.set('upper', { rot: [0, 0, J.q1] });
      api.set('fore', { rot: [0, 0, J.q2] });
      api.set('wrist', { rot: [0, 0, J.wr] });
      fingerAng.forEach((a, i) => api.set('finger' + i, { pos: [0, rF, 0] }));
      api.set('pawnW', { pos: pawnW(u), opacity: resetA(u) });
      api.set('pawnB', { pos: pawnB(u), opacity: resetA(u) });
      const hp = pinch(u), handIn = u < 0.18;
      api.set('hand', { pos: hp, visible: handIn });
    },
    readout(u) {
      const J = ik(tip(u)), st = u < 0.18 ? '你走 e2→e4' : u < 0.3 ? '识别：e2 空了，e4 多一颗白兵' : u < 0.4 ? 'AI：走 e7→e5' : u < 0.84 ? (heldB(u) ? '搬运 e7→e5' : '对准 e7') : '待机';
      return `${st} · 转台 ${J.psi.toFixed(0)}° · 肩 ${J.q1.toFixed(0)}° · 肘 ${J.q2.toFixed(0)}° · 爪 ${openF(u) > 0.5 ? '张开' : '夹紧'}`;
    },
    caption: '依据：产品规格（SenseRobot，B&H 规格页：4 自由度机械臂、对局摄像头、磁吸棋盘、57 × 47 × 38.5 cm、5 kg、最高标称 ELO 3200）；厂商宣称（三指软爪、识别率超过 99.9%）。' +
      '模拟假设：关节排法、杆长、摄像头支架位置、走法 e2–e4 / e7–e5 都是示意。'
  };
};

export const { createScene, mount } = defineModel(makeScene, {"id":"chess-robot","figure":6});
